// Generated by @canonical/summon-component:react v0.43.0

import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import CountLine from "./CountLine.js";

describe("CountLine", () => {
  it("counts the shown entries of an exact total", () => {
    render(
      <CountLine
        kind="stations"
        shown={4}
        total={{ kind: "exact", value: 48 }}
      />,
    );
    expect(screen.getByRole("status")).toHaveTextContent("4 of 48 stations");
  });

  it("marks a total known only as a lower bound", () => {
    render(
      <CountLine
        kind="components"
        shown={100}
        total={{ kind: "at-least", value: 100 }}
      />,
    );
    expect(screen.getByRole("status")).toHaveTextContent(
      "100 of 100+ components",
    );
  });

  it("counts the shown entries alone when the total is unknown", () => {
    render(<CountLine kind="lines" shown={3} total={{ kind: "unknown" }} />);
    expect(screen.getByRole("status")).toHaveTextContent("3 lines");
  });

  it("announces a change politely", () => {
    render(<CountLine kind="lines" shown={3} total={{ kind: "unknown" }} />);
    expect(screen.getByRole("status")).toHaveAttribute("aria-live", "polite");
  });

  it("applies custom className and passes native props through", () => {
    render(
      <CountLine
        className="custom-class"
        data-testid="count"
        kind="lines"
        shown={1}
        total={{ kind: "unknown" }}
      />,
    );
    const count = screen.getByTestId("count");
    expect(count.className).toContain("ds count-line");
    expect(count.className).toContain("custom-class");
  });
});
